param(
    [switch]$Push = $true
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$Root = "C:\Users\arauj\grafica-flash"
$Target = Join-Path $Root "components\parceiros\PartnerCoursesTab.tsx"
Set-Location -LiteralPath $Root

function Step([string]$Message) {
    Write-Host ""
    Write-Host "==> $Message" -ForegroundColor Cyan
}

function Resolve-Cmd([string]$Name) {
    foreach ($candidate in @("$Name.cmd", $Name)) {
        $cmd = Get-Command $candidate -ErrorAction SilentlyContinue
        if ($cmd) { return $cmd.Source }
    }
    throw "Command not found: $Name"
}

function Run([string]$Command, [string[]]$Arguments) {
    & $Command @Arguments
    if ($LASTEXITCODE -ne 0) {
        throw "Failed: $Command $($Arguments -join ' ')"
    }
}

$Git = Resolve-Cmd "git"
$Npm = Resolve-Cmd "npm"
$Npx = Resolve-Cmd "npx"

if (-not (Test-Path -LiteralPath $Target)) {
    throw "PartnerCoursesTab.tsx not found."
}

Step "Writing advanced course platform"

$Base64 = ""
$Bytes = [Convert]::FromBase64String($Base64)
[System.IO.File]::WriteAllBytes($Target, $Bytes)

Step "ESLint"
Run $Npx @(
    "eslint",
    "components/parceiros/PartnerCoursesTab.tsx"
)

Step "Build"
Run $Npm @("run", "build")

Step "Diff check"
Run $Git @(
    "diff",
    "--check",
    "--",
    "components/parceiros/PartnerCoursesTab.tsx"
)

& $Git --no-pager diff --stat -- "components/parceiros/PartnerCoursesTab.tsx"

Step "Commit"
Run $Git @(
    "add",
    "--",
    "components/parceiros/PartnerCoursesTab.tsx"
)

Run $Git @(
    "diff",
    "--cached",
    "--check",
    "--",
    "components/parceiros/PartnerCoursesTab.tsx"
)

& $Git diff --cached --quiet -- "components/parceiros/PartnerCoursesTab.tsx"

if ($LASTEXITCODE -eq 0) {
    throw "No course changes to commit."
}

Run $Git @(
    "commit",
    "-m",
    "Aprofunda academia de cursos dos parceiros",
    "--",
    "components/parceiros/PartnerCoursesTab.tsx"
)

if ($Push) {
    $branch = (& $Git branch --show-current).Trim()
    if (-not $branch) {
        throw "Could not resolve current branch."
    }

    Step "Push"
    Run $Git @(
        "push",
        "-u",
        "origin",
        $branch
    )
}

Write-Host ""
Write-Host "ORCALY_PARTNER_ACADEMY_V2_OK=1" -ForegroundColor Green
Write-Host "Interactive lessons: OK" -ForegroundColor Cyan
Write-Host "Detailed content: OK" -ForegroundColor Cyan
Write-Host "Local progress: OK" -ForegroundColor Cyan
